package com.primehr.succession.api;
import com.primehr.security.*;import com.primehr.succession.application.SuccessionDevelopmentService;import com.primehr.succession.api.SuccessionDevelopmentDtos.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/succession/development")public class SuccessionDevelopmentController{
 private final SuccessionDevelopmentService service;private final SuccessionPlanningPermissionGuard permission;private final AgencyScopeResolver agency;public SuccessionDevelopmentController(SuccessionDevelopmentService service,SuccessionPlanningPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}
 @GetMapping public List<PlanResponse>list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a),a.getName(),s);}
 @GetMapping("/{id}")public PlanResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id,a.getName(),s);}
 @PostMapping("/decisions/{decisionId}")@ResponseStatus(HttpStatus.CREATED)public PlanResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String decisionId,@Valid@RequestBody CreatePlanInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.ADD,t);return service.create(agency.resolveAgencyId(a),decisionId,i,a.getName(),s,c);}
 @PutMapping("/{id}")public PlanResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody UpdatePlanInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.EDIT,t);return service.update(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/{id}/sources")public PlanResponse source(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody SourceInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.EDIT,t);return service.addSource(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/{id}/milestones")public PlanResponse milestone(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody MilestoneInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.EDIT,t);return service.addMilestone(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PutMapping("/{id}/milestones/{milestoneId}/status")public PlanResponse milestoneStatus(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String milestoneId,@Valid@RequestBody MilestoneStatusInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.EDIT,t);return service.updateMilestone(agency.resolveAgencyId(a),id,milestoneId,i,a.getName(),s,c);}
 @PostMapping("/{id}/activation")public PlanResponse activate(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody VersionInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.PUBLISH,t);return service.activate(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/{id}/acknowledgment")public PlanResponse acknowledge(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody AcknowledgmentInput i){permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.ACCESS,t);return service.acknowledge(agency.resolveAgencyId(a),id,i,a.getName(),c);}
 @PostMapping("/{id}/reviews")public PlanResponse review(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReviewInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.SUBMIT,t);return service.review(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/{id}/completion")public PlanResponse complete(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody VersionInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.APPROVE,t);return service.complete(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/{id}/membership-events")public PlanResponse membership(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody MembershipInput i){var s=permission.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.FINALIZE,t);return service.membership(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
}
